def decl_files(leaf):
    pat=re.compile(r'"'^[ '"\\t]*(?:@["'^'"\\n]*\\n[ \\t]*)*(?:protected[ \\t]+|private[ \\t]+|noncomputable[ \\t]+)*' +
                   r'(?:theorem|lemma|def|abbrev|structure|class|inductive|instance|axiom|opaque)[ \\t]+(?:["'^ '"\\t(]+[ \\t]+)*' + re.escape(leaf) + r'(?=[ \\t(:{\\n])',
